"""Compare the Python loaders to output generated by the original MATLAB logic run in Octave.

Regenerate the golden files with ``octave --no-gui tools/octave/golden_load.m`` (repository root).
Golden time is in milliseconds (MATLAB units); the Python schema uses seconds.
"""

from pathlib import Path

import numpy as np
import pytest

from ikd1d.io import load_biodex, load_cybex
from ikd1d.schema import COLUMNS

HERE = Path(__file__).parent
CASES = [
    ("Biodex_system3_Qcon120-Hcon120", "txt", load_biodex),
    ("Biodex_system3_QNaN-Hecc120", "txt", load_biodex),
    ("Cybex_Qcon60-Hcon60", "CSV", load_cybex),
]


@pytest.mark.parametrize(("name", "ext", "loader"), CASES)
def test_loader_matches_matlab_golden(name, ext, loader):
    golden = np.loadtxt(HERE / "golden" / f"{name}.csv", delimiter=",")
    got = loader(HERE / "data" / f"{name}.{ext}")
    assert got.shape == golden.shape
    np.testing.assert_allclose(got["time"] * 1000.0, golden[:, 0], atol=1e-6)
    for i, col in enumerate(COLUMNS[1:], start=1):
        np.testing.assert_allclose(got[col], golden[:, i], rtol=0, atol=1e-9, err_msg=col)
